<?php
declare(strict_types=1);
date_default_timezone_set('Asia/Karachi');
require_once __DIR__ . '/../app/bootstrap.php';
$user = require_role('admin');
$pdo = db();
function sd_rep_h(string $v): string { return htmlspecialchars($v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function sd_rep_date_valid(string $v): bool { $d=DateTimeImmutable::createFromFormat('!Y-m-d',$v,new DateTimeZone('Asia/Karachi')); $e=DateTimeImmutable::getLastErrors(); return $d!==false && $d->format('Y-m-d')===$v && (!is_array($e)||($e['warning_count']===0&&$e['error_count']===0)); }
$today=date('Y-m-d'); $defaultFrom=date('Y-m-01'); $from=(string)($_GET['from']??$defaultFrom); $to=(string)($_GET['to']??$today); $filterError='';
if (!sd_rep_date_valid($from) || !sd_rep_date_valid($to) || $from>$to) { $from=$defaultFrom; $to=$today; $filterError='The date range was invalid, so the current month has been selected.'; }
$fromDate=new DateTimeImmutable($from.' 00:00:00',new DateTimeZone('Asia/Karachi')); $endExclusive=(new DateTimeImmutable($to.' 00:00:00',new DateTimeZone('Asia/Karachi')))->modify('+1 day');
if ((int)$fromDate->diff($endExclusive)->days>366) { $from=$defaultFrom; $to=$today; $fromDate=new DateTimeImmutable($from.' 00:00:00',new DateTimeZone('Asia/Karachi')); $endExclusive=(new DateTimeImmutable($to.' 00:00:00',new DateTimeZone('Asia/Karachi')))->modify('+1 day'); $filterError='Date ranges are limited to 366 days. The current month has been selected.'; }
$fromSql=$fromDate->format('Y-m-d H:i:s'); $toSql=$endExclusive->format('Y-m-d H:i:s');
try {
    $q=$pdo->prepare("SELECT COUNT(*) total, SUM(status='confirmed') confirmed_count, SUM(status='completed') completed_count, SUM(status='cancelled') cancelled_count, SUM(status='no_show') no_show_count FROM appointments WHERE starts_at>=? AND starts_at<?"); $q->execute([$fromSql,$toSql]); $summary=$q->fetch() ?: [];
    $q=$pdo->prepare("SELECT COALESCE(SUM(service_price_snapshot),0) revenue FROM appointments WHERE status='completed' AND starts_at>=? AND starts_at<?"); $q->execute([$fromSql,$toSql]); $revenue=(float)$q->fetchColumn();
    $q=$pdo->prepare("SELECT service_name_snapshot service_name,COUNT(*) bookings,COALESCE(SUM(CASE WHEN status='completed' THEN service_price_snapshot ELSE 0 END),0) revenue FROM appointments WHERE status IN ('confirmed','completed') AND starts_at>=? AND starts_at<? GROUP BY service_name_snapshot ORDER BY bookings DESC,revenue DESC LIMIT 10"); $q->execute([$fromSql,$toSql]); $popular=$q->fetchAll();
    $q=$pdo->prepare("SELECT u.name stylist_name,COUNT(*) completed_count,COALESCE(SUM(a.service_price_snapshot),0) revenue FROM appointments a JOIN users u ON u.id=a.stylist_user_id WHERE a.status='completed' AND a.starts_at>=? AND a.starts_at<? GROUP BY u.id,u.name ORDER BY revenue DESC,completed_count DESC"); $q->execute([$fromSql,$toSql]); $staffPerf=$q->fetchAll();
    $q=$pdo->prepare("SELECT HOUR(starts_at) booking_hour,COUNT(*) bookings FROM appointments WHERE status IN ('confirmed','completed') AND starts_at>=? AND starts_at<? GROUP BY HOUR(starts_at) ORDER BY bookings DESC,booking_hour ASC LIMIT 6"); $q->execute([$fromSql,$toSql]); $peakHours=$q->fetchAll();
    $q=$pdo->prepare("SELECT i.id,i.name,i.unit,i.quantity_on_hand,i.reorder_level,i.unit_cost,COALESCE(SUM(CASE WHEN m.movement_type='use' THEN -m.quantity_delta ELSE 0 END),0) used_quantity,COALESCE(SUM(CASE WHEN m.movement_type='restock' THEN m.quantity_delta ELSE 0 END),0) restocked_quantity FROM inventory_items i LEFT JOIN inventory_movements m ON m.item_id=i.id AND m.created_at>=? AND m.created_at<? WHERE i.is_active=1 GROUP BY i.id,i.name,i.unit,i.quantity_on_hand,i.reorder_level,i.unit_cost ORDER BY used_quantity DESC,i.name"); $q->execute([$fromSql,$toSql]); $inventoryUsage=$q->fetchAll();
    $q=$pdo->prepare("SELECT DATE(created_at) movement_day,SUM(CASE WHEN movement_type='use' THEN -quantity_delta ELSE 0 END) used_quantity,SUM(CASE WHEN movement_type='restock' THEN quantity_delta ELSE 0 END) restocked_quantity FROM inventory_movements WHERE created_at>=? AND created_at<? GROUP BY DATE(created_at) ORDER BY movement_day ASC"); $q->execute([$fromSql,$toSql]); $inventoryTrend=$q->fetchAll();
    $lowStock=$pdo->query('SELECT name,quantity_on_hand,reorder_level,unit FROM inventory_items WHERE is_active=1 AND quantity_on_hand<=reorder_level ORDER BY quantity_on_hand ASC,name LIMIT 20')->fetchAll();
    $revenueByService=$pdo->prepare("SELECT service_name_snapshot service_name,SUM(service_price_snapshot) revenue FROM appointments WHERE status='completed' AND starts_at>=? AND starts_at<? GROUP BY service_name_snapshot ORDER BY revenue DESC LIMIT 8"); $revenueByService->execute([$fromSql,$toSql]); $revenueServices=$revenueByService->fetchAll();
} catch(Throwable $e) {
    error_log('SalonDiva reports error: '.$e->getMessage()); http_response_code(500);
    echo '<!doctype html><meta charset="utf-8"><h1>Reports setup is incomplete</h1><p>Run the Appointment Booking, Staff Operations, and Calendar & Analytics database migrations, then refresh this page.</p>'; exit;
}
$maxService=max(array_map(fn($x)=>(float)$x['bookings'],$popular)?:[1]); $maxRevenue=max(array_map(fn($x)=>(float)$x['revenue'],$revenueServices)?:[1]); $maxHour=max(array_map(fn($x)=>(float)$x['bookings'],$peakHours)?:[1]); $maxUse=max(array_map(fn($x)=>(float)$x['used_quantity'],$inventoryUsage)?:[1]);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports & Analytics · SalonDiva</title><style>
:root{--ink:#321d2a;--pink:#c52f63;--bg:#fff6f9;--line:#ead8e1;--muted:#806c77;--cream:#fffdf9;--green:#e3f5e8;--red:#fbe4e8;--gold:#fff1ce}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}.wrap{max-width:1280px;margin:24px auto;padding:0 14px}.shell{background:var(--cream);border:1px solid var(--line);border-radius:20px;padding:clamp(14px,2.5vw,26px)}.brand{font-weight:850;color:var(--pink)}h1{margin:.25rem 0}h2{margin:0 0 12px;font-size:1.15rem}.muted,.hint{color:var(--muted)}.nav{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.btn{display:inline-block;background:var(--pink);color:#fff;padding:9px 12px;border-radius:9px;text-decoration:none;font-weight:700;border:0;cursor:pointer}.btn.light{background:#f5e5ec;color:var(--ink)}.filter,.panel{background:white;border:1px solid var(--line);border-radius:14px;padding:15px;margin-top:15px}.filterform{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.field{display:flex;flex-direction:column;gap:5px}.field input{padding:9px;border:1px solid #dfcbd4;border-radius:8px;font:inherit}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-top:15px}.stat{background:#fff;border:1px solid var(--line);padding:14px;border-radius:13px}.stat span{font-size:.86rem;color:var(--muted);display:block}.stat strong{font-size:1.45rem;display:block;margin-top:4px}.two{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px;margin-top:14px}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:510px}td,th{padding:9px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line)}th{background:#fbf0f4}.barrow{display:grid;grid-template-columns:minmax(90px,1.2fr) minmax(90px,2fr) auto;align-items:center;gap:8px;margin:10px 0}.barbg{height:12px;border-radius:99px;background:#f4e4eb;overflow:hidden}.bar{height:100%;background:var(--pink);border-radius:99px;min-width:0}.notice{border-radius:9px;padding:10px;background:var(--gold);margin:12px 0}.pill{padding:3px 7px;border-radius:99px;background:var(--gold)}@media(max-width:600px){.barrow{grid-template-columns:85px 1fr}.barrow .value{grid-column:2}}
</style></head><body><main class="wrap"><div class="shell"><div class="brand">SalonDiva</div><h1>Reports & analytics</h1><p class="muted">Use the date range to review appointment outcomes, completed-service revenue, staff performance, busy booking times, and inventory activity.</p><div class="nav"><a class="btn light" href="dashboard.php">Dashboard</a><a class="btn light" href="calendar.php">Calendar</a><a class="btn light" href="appointments.php">Appointments</a><a class="btn light" href="inventory.php">Manage inventory</a></div>
<?php if($filterError!==''): ?><div class="notice"><?=sd_rep_h($filterError)?></div><?php endif; ?><section class="filter"><form class="filterform" method="get"><div class="field"><label for="from">From</label><input id="from" type="date" name="from" value="<?=sd_rep_h($from)?>" required></div><div class="field"><label for="to">To</label><input id="to" type="date" name="to" value="<?=sd_rep_h($to)?>" required></div><button class="btn" type="submit">Apply range</button></form><p class="hint">Reports use appointment start date and inventory movement creation date. Range is limited to 366 days.</p></section>
<div class="stats"><div class="stat"><span>Appointments</span><strong><?=number_format((int)($summary['total']??0))?></strong></div><div class="stat"><span>Confirmed</span><strong><?=number_format((int)($summary['confirmed_count']??0))?></strong></div><div class="stat"><span>Completed</span><strong><?=number_format((int)($summary['completed_count']??0))?></strong></div><div class="stat"><span>Cancelled</span><strong><?=number_format((int)($summary['cancelled_count']??0))?></strong></div><div class="stat"><span>No-shows</span><strong><?=number_format((int)($summary['no_show_count']??0))?></strong></div><div class="stat"><span>Completed-service revenue</span><strong>PKR <?=number_format($revenue,2)?></strong></div></div>
<div class="notice">Revenue is an estimate based on the saved service price of appointments marked completed. It does not include separate product sales, taxes, discounts, refunds, or payment reconciliation because those are not recorded by this starter update.</div>
<div class="two"><section class="panel"><h2>Popular services</h2><?php if(!$popular): ?><p class="muted">No completed appointments in this range.</p><?php endif; ?><?php foreach($popular as $s): $pct=(int)round(100*(float)$s['bookings']/$maxService); ?><div class="barrow"><div><?=sd_rep_h((string)$s['service_name'])?></div><div class="barbg"><div class="bar" style="width:<?=$pct?>%"></div></div><div class="value"><?=number_format((int)$s['bookings'])?> bookings</div></div><?php endforeach; ?></section>
<section class="panel"><h2>Revenue by service</h2><?php if(!$revenueServices): ?><p class="muted">No completed-service revenue in this range.</p><?php endif; ?><?php foreach($revenueServices as $s): $pct=(int)round(100*(float)$s['revenue']/$maxRevenue); ?><div class="barrow"><div><?=sd_rep_h((string)$s['service_name'])?></div><div class="barbg"><div class="bar" style="width:<?=$pct?>%"></div></div><div class="value">PKR <?=number_format((float)$s['revenue'],2)?></div></div><?php endforeach; ?></section></div>
<div class="two"><section class="panel"><h2>Peak booking hours</h2><p class="hint">Counts confirmed and completed appointments by start hour.</p><?php if(!$peakHours): ?><p class="muted">No bookings in this range.</p><?php endif; ?><?php foreach($peakHours as $h): $hour=(int)$h['booking_hour']; $label=date('g A',strtotime(sprintf('%02d:00:00',$hour))); $pct=(int)round(100*(float)$h['bookings']/$maxHour); ?><div class="barrow"><div><?=sd_rep_h($label)?></div><div class="barbg"><div class="bar" style="width:<?=$pct?>%"></div></div><div class="value"><?=number_format((int)$h['bookings'])?> bookings</div></div><?php endforeach; ?></section>
<section class="panel"><h2>Staff performance</h2><div class="tablewrap"><table><thead><tr><th>Stylist</th><th>Completed</th><th>Service revenue</th></tr></thead><tbody><?php foreach($staffPerf as $s): ?><tr><td><?=sd_rep_h((string)$s['stylist_name'])?></td><td><?=number_format((int)$s['completed_count'])?></td><td>PKR <?=number_format((float)$s['revenue'],2)?></td></tr><?php endforeach; ?><?php if(!$staffPerf): ?><tr><td colspan="3">No completed services in this range.</td></tr><?php endif; ?></tbody></table></div><p class="hint">This measures service revenue assigned to a stylist, not net profit or commission pay-outs.</p></section></div>
<div class="two"><section class="panel"><h2>Inventory usage and restocks</h2><div class="tablewrap"><table><thead><tr><th>Item</th><th>Used</th><th>Restocked</th><th>On hand now</th></tr></thead><tbody><?php foreach($inventoryUsage as $i): ?><tr><td><?=sd_rep_h((string)$i['name'])?></td><td><?=number_format((float)$i['used_quantity'],3)?> <?=sd_rep_h((string)$i['unit'])?></td><td><?=number_format((float)$i['restocked_quantity'],3)?> <?=sd_rep_h((string)$i['unit'])?></td><td><?=number_format((float)$i['quantity_on_hand'],3)?> <?=sd_rep_h((string)$i['unit'])?></td></tr><?php endforeach; ?><?php if(!$inventoryUsage): ?><tr><td colspan="4">No inventory items. Add items in Manage inventory.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><h2>Low stock alerts</h2><div class="tablewrap"><table><thead><tr><th>Item</th><th>On hand</th><th>Reorder level</th></tr></thead><tbody><?php foreach($lowStock as $i): ?><tr><td><?=sd_rep_h((string)$i['name'])?></td><td><span class="pill"><?=number_format((float)$i['quantity_on_hand'],3)?> <?=sd_rep_h((string)$i['unit'])?></span></td><td><?=number_format((float)$i['reorder_level'],3)?></td></tr><?php endforeach; ?><?php if(!$lowStock): ?><tr><td colspan="3">No active items at or below reorder level.</td></tr><?php endif; ?></tbody></table></div></section></div>
<section class="panel"><h2>Inventory usage trend by day</h2><div class="tablewrap"><table><thead><tr><th>Date</th><th>Quantity used</th><th>Quantity restocked</th></tr></thead><tbody><?php foreach(array_reverse($inventoryTrend) as $t): ?><tr><td><?=sd_rep_h(date('D, d M Y',strtotime((string)$t['movement_day'])))?></td><td><?=number_format((float)$t['used_quantity'],3)?></td><td><?=number_format((float)$t['restocked_quantity'],3)?></td></tr><?php endforeach; ?><?php if(!$inventoryTrend): ?><tr><td colspan="3">No stock movements in this range. Record restocks or usage on the Inventory page to build trend data.</td></tr><?php endif; ?></tbody></table></div></section>
</div></main></body></html>
